// Music responds to visible events, never to an unobserved visitor's true identity.
export function musicPhase(s){if(s.threats?.some(t=>t.mode!=='dead'))return'chase';if(!s.power||s.phase==='outage')return'outage';if(s.shadow||s.flickerUntil>s.time||s.alleyEvent&&s.time-s.alleyEvent.time<6)return'doubt';return'business';}
const STYLES=['ambient'],KEY='exit-nine:player:music:choice:approved-v3';
const MUSIC_REVISION=style=>style==='ambient'?'v3':'v1';
export class MusicDirector{
 constructor(audio){this.audio=audio;this.style=null;this.volume=.28;this.buffers=new Map();this.events=[];this.bus=null;this.source=null;this.current=null;this.loading=null;this.generation=0;this.nextRead=0;this.defaultStyle='ambient';fetch('./assets/music/config.json').then(r=>r.json()).then(v=>{this.defaultStyle=STYLES.includes(v.selected)?v.selected:null;this.nextRead=0;}).catch(()=>{});}
 select(style){if(style&&!STYLES.includes(style))return;try{localStorage.setItem(KEY,style||'none');}catch{}this.setStyle(style);}
 setStyle(style){if(style===this.style)return;this.style=style;this.generation++;this.loading=null;this.current=null;this.buffers.clear();this.stop();}
 stop(){if(this.source){try{this.source.node.stop();}catch{}this.source.node.disconnect();this.source.gain.disconnect();this.source=null;}}
 async cue(state){const c=this.audio.context;if(!c||!this.style)return;const key=this.style+'-'+state;if(this.current===key||this.loading===key)return;this.loading=key;const generation=this.generation;try{let buffer=this.buffers.get(key);if(!buffer){const r=await fetch(new URL('./assets/music/'+MUSIC_REVISION(this.style)+'/'+key+'.wav',import.meta.url));if(!r.ok)throw Error('music HTTP '+r.status);buffer=await c.decodeAudioData(await r.arrayBuffer());this.buffers.set(key,buffer);}if(generation!==this.generation||this.loading!==key)return;if(!this.bus){this.bus=c.createGain();this.bus.gain.value=0;this.bus.connect(this.audio.master);}const previous=this.source,node=c.createBufferSource(),gain=c.createGain();node.buffer=buffer;node.loop=true;gain.gain.setValueAtTime(0,c.currentTime);gain.gain.linearRampToValueAtTime(1,c.currentTime+1.4);node.connect(gain);gain.connect(this.bus);node.start();this.source={node,gain};this.current=key;this.loading=null;this.events.push({style:this.style,state,time:c.currentTime});if(previous){previous.gain.gain.cancelScheduledValues(c.currentTime);previous.gain.gain.setTargetAtTime(0,c.currentTime,.25);previous.node.stop(c.currentTime+1.5);previous.node.onended=()=>{previous.node.disconnect();previous.gain.disconnect();};}}catch(e){if(generation===this.generation){this.loading=null;this.events.push({key,error:e.message});}}}
 update(s,{opening=false,voice=false,paused=s.paused}={}){const now=performance.now();if(now>=this.nextRead){this.nextRead=now+1000;let style=this.defaultStyle;try{const choice=localStorage.getItem(KEY);if(choice!=null)style=STYLES.includes(choice)?choice:null;}catch{}this.setStyle(style);}if(!this.audio.master)return;const c=this.audio.context;if(!this.style){if(this.bus)this.bus.gain.setTargetAtTime(0,c.currentTime,.12);return;}let state=opening?'business':musicPhase(s);if(state==='doubt')this.doubtUntil=(s.time||0)+8;else if(state==='business'&&(s.time||0)<(this.doubtUntil||0))state='doubt';if(!paused&&!s.finished)this.cue(state);const speech=voice||s.subtitleUntil>s.time,level=paused||s.finished?0:this.volume*(opening?.65:1)*(speech?.35:1);if(this.bus)this.bus.gain.setTargetAtTime(level,c.currentTime,.24);}
}
